include "globals.mzn";

enum COLOR = {Red, Blue, Green, Ivory, Yellow};
enum NATIONALITY = {Englishman, Spaniard, Ukrainian, Norwegian, Japanese};
enum DRINK = {Tea, Coffee, Milk, OrangeJuice, Water};
enum CIGAR = {OldGold, Kools, Chesterfields, LuckyStrike, Parliaments};
enum PET = {Dog, Snails, Fox, Horse, Zebra};

int: N = 5;

array[1..N] of var COLOR: color;
array[1..N] of var NATIONALITY: nationality;
array[1..N] of var DRINK: drink;
array[1..N] of var CIGAR: cigar;
array[1..N] of var PET: pet;

constraint color[1] != color[2] /\ color[1] != color[3] /\ color[1] != color[4] /\ color[1] != color[5] /\ 
          color[2] != color[3] /\ color[2] != color[4] /\ color[2] != color[5] /\
          color[3] != color[4] /\ color[3] != color[5] /\ 
          color[4] != color[5];

constraint nationality[1] != nationality[2] /\ nationality[1] != nationality[3] /\ nationality[1] != nationality[4] /\ 
          nationality[1] != nationality[5] /\ 
          nationality[2] != nationality[3] /\ nationality[2] != nationality[4] /\ nationality[2] != nationality[5] /\
          nationality[3] != nationality[4] /\ nationality[3] != nationality[5] /\ 
          nationality[4] != nationality[5];

constraint drink[1] != drink[2] /\ drink[1] != drink[3] /\ drink[1] != drink[4] /\ 
          drink[1] != drink[5] /\ 
          drink[2] != drink[3] /\ drink[2] != drink[4] /\ drink[2] != drink[5] /\
          drink[3] != drink[4] /\ drink[3] != drink[5] /\ 
          drink[4] != drink[5];

constraint cigar[1] != cigar[2] /\ cigar[1] != cigar[3] /\ cigar[1] != cigar[4] /\ 
          cigar[1] != cigar[5] /\ 
          cigar[2] != cigar[3] /\ cigar[2] != cigar[4] /\ cigar[2] != cigar[5] /\
          cigar[3] != cigar[4] /\ cigar[3] != cigar[5] /\ 
          cigar[4] != cigar[5];

constraint pet[1] != pet[2] /\ pet[1] != pet[3] /\ pet[1] != pet[4] /\ 
          pet[1] != pet[5] /\ 
          pet[2] != pet[3] /\ pet[2] != pet[4] /\ pet[2] != pet[5] /\
          pet[3] != pet[4] /\ pet[3] != pet[5] /\ 
          pet[4] != pet[5];

constraint nationality[1] = Norwegian;
constraint drink[3] = Milk;
constraint nationality[find(i in 1..N where nationality[i] = Englishman)] = color[find(i in 1..N where color[i] = Red)];
constraint nationality[find(i in 1..N where nationality[i] = Spaniard)] = pet[find(i in 1..N where pet[i] = Dog)];
constraint drink[find(i in 1..N where color[i] = Green)] = Coffee;
constraint nationality[find(i in 1..N where nationality[i] = Ukrainian)] = drink[find(i in 1..N where drink[i] = Tea)];
constraint color[find(i in 1..N where color[i] = Green)] = color[find(i in 1..N where color[i] = Ivory) + 1];
constraint nationality[find(i in 1..N where cigar[i] = OldGold)] = pet[find(i in 1..N where pet[i] = Snails)];
constraint cigar[find(i in 1..N where cigar[i] = Kools)] = color[find(i in 1..N where color[i] = Yellow)];
constraint drink[find(i in 1..N where cigar[i] = LuckyStrike)] = drink[find(i in 1..N where drink[i] = OrangeJuice)];
constraint nationality[find(i in 1..N where nationality[i] = Japanese)] = cigar[find(i in 1..N where cigar[i] = Parliaments)];
constraint color[find(i in 1..N where nationality[i] = Norwegian)] = color[find(i in 1..N where color[i] = Blue)];

forall(i in 1..N)(exists(j in 1..N)(abs(i - j) = 1 /\ cigar[i] = Chesterfields /\ pet[j] = Fox));
forall(i in 1..N)(exists(j in 1..N)(abs(i - j) = 1 /\ cigar[i] = Kools /\ pet[j] = Horse));

include "globals.mzn";

enum COLOR = { Blue, Red, Green };
enum ANIMAL = { Dog, Cat, Zebra };
array[1..3] of var COLOR: houseColor;
array[1..3] of var ANIMAL: houseAnimal;

constraint houseColor[2] = Red;
constraint houseColor[1] = Blue; 
constraint houseAnimal[1] = Dog; 
constraint houseAnimal[2] = Cat; 
constraint houseAnimal[3] = Zebra;

constraint alldifferent(houseColor);
constraint alldifferent(houseAnimal);

include "globals.mzn";

enum Choice = { Paper, Rock, Scissors };

var Choice: player1;
var Choice: player2;

constraint player2 = Rock;
constraint (player1 = Paper) \/ (player2 = Rock);
constraint (player1 = Rock) \/ (player2 = Scissors);
constraint (player1 = Scissors) \/ (player2 = Paper);

include "globals.mzn";

enum Suspect = { Miss_Scarlett, Colonel_Mustard, Professor_Plum };
enum Weapon = { Candlestick, Revolver, Rope };
enum Room = { Kitchen, Library, Conservatory };

var Suspect: culprit;
var Weapon: murder_weapon;
var Room: murder_location;

constraint culprit != Colonel_Mustard;
constraint culprit != Miss_Scarlett;
constraint murder_weapon != Revolver;
constraint murder_weapon != Rope;
constraint murder_location != Kitchen;
constraint murder_location != Library;

constraint alldifferent([culprit, murder_weapon, murder_location]);

include "globals.mzn";

enum LETTER = {S, E, N, D, M, O, R, Y};

array[LETTER] of var 0..9: letterValue;
constraint
    letterValue[S] > 0 /\
    letterValue[M] > 0 /\
    alldifferent(letterValue) /\
    letterValue[M] = 1 /\
    (letterValue[S] >= 9) /\
    (letterValue[S] * 1000 + letterValue[E] * 100 + letterValue[N] * 10 + letterValue[D]) +
    (letterValue[M] * 1000 + letterValue[O] * 100 + letterValue[R] * 10 + letterValue[E]) =
    (letterValue[M] * 10000 + letterValue[O] * 1000 + letterValue[N] * 100 + letterValue[E] * 10 + letterValue[Y]);

include "globals.mzn";

enum Direction = {North, South, East, West};

array[Direction] of var 1..4: arrivalTime;

constraint arrivalTime[South] < arrivalTime[East] /\ 
          arrivalTime[South] < arrivalTime[North] /\ 
          arrivalTime[South] < arrivalTime[West];

constraint arrivalTime[East] = arrivalTime[North] /\ 
          arrivalTime[East] = arrivalTime[West];

constraint arrivalTime[North] > arrivalTime[East] /\ 
          arrivalTime[West] > arrivalTime[East];

constraint arrivalTime[North] > arrivalTime[South] /\ 
          arrivalTime[West] > arrivalTime[South];

constraint arrivalTime[North] < arrivalTime[West];

include "globals.mzn";

enum Outcome = {Denied, Approved, CounterOffer};

int: priyaCreditScore = 680;
int: samCreditScore = 750;
int: lowerCreditTier = min(priyaCreditScore, samCreditScore); 
int: combinedMonthlyIncome = 9000;
int: combinedMonthlyDebt = 3200;
var Outcome: loanOutcome;
int: requestedLoanAmount;
int: policyLimit;

constraint lowerCreditTier < 600 -> loanOutcome = Denied;
constraint combinedMonthlyDebt / combinedMonthlyIncome > 0.43 -> loanOutcome = Denied;
constraint loanOutcome != Denied -> (requestedLoanAmount <= policyLimit -> loanOutcome = Approved);
constraint loanOutcome != Denied /\ requestedLoanAmount > policyLimit -> loanOutcome = CounterOffer;

include "globals.mzn";

enum DRUG = { Drug_A, Drug_B, Drug_C };
enum TIME = { 9, 11, 16 }; % 9am, 11am, 4pm
array[DRUG] of var TIME: drugTime;

constraint 
    drugTime[Drug_B] >= drugTime[Drug_A] + 4 /\
    drugTime[Drug_C] >= 8 /\
    drugTime[Drug_C] >= 2 + drugTime[Drug_A] /\
    drugTime[Drug_C] != 9 /\
    drugTime[Drug_C] != 11 /\
    drugTime[Drug_C] == 16 /\
    (drugTime[Drug_A] == 9 -> drugTime[Drug_B] >= 13) /\
    (drugTime[Drug_A] == 11 -> drugTime[Drug_B] >= drugTime[Drug_A]);

include "globals.mzn";

enum NEIGHBORS = { Ana, Bo, Cy };
array[1..3] of var NEIGHBORS: neighbor;

constraint neighbor[1] = Ana;
constraint neighbor[2] != Bo;
constraint alldifferent(neighbor);

constraint forall(i in 1..3)(exists(j in 1..3)(neighbor[j] = neighbor[i]));

include "globals.mzn";

enum ITEM = { RICE, BOOKSET, SKILLET, FIRST_AID, TOOLBOX };

array[ITEM] of int: weights = [4, 3, 5, 2, 6];
array[ITEM] of int: values = [5, 4, 8, 6, 7];

array[ITEM] of var 0..1: selected; 

constraint sum(i in ITEM)(weights[i] * selected[i]) <= 10;

constraint selected[FIRST_AID] == 1;

constraint forall(i in ITEM)(selected[i] <= 1);

constraint sum(i in ITEM)(weights[i] * selected[i]) + weights[FIRST_AID] <= 10;

include "globals.mzn";

enum Color = {Red, Blue, Green, Yellow, White};
array[1..5] of var Color: houseColor;

constraint houseColor[1] = Red;
constraint houseColor[4] = White;
constraint exists(i in 1..4)(exists(j in (i+1)..5)(houseColor[i] = Blue /\ houseColor[j] = Green));
constraint alldifferent(houseColor);

include "globals.mzn";

enum GroceryItem = { Tub_of_Ice_Cream, Can_of_Beans, Bag_of_Flour, Bunch_of_Bananas };
enum Compartment = { Compartment_1, Compartment_2, Compartment_3, Compartment_4 };

array[1..4] of var GroceryItem: items;
array[1..4] of var Compartment: compartments;

constraint
    forall(i in 1..4) (
        items[i] in GroceryItem
    ) /\
    alldifferent(items) /\
    forall(i in 1..4) (
        compartments[i] in Compartment
    ) /\
    alldifferent(compartments) /\
    (items[1] = Tub_of_Ice_Cream -> compartments[1] = Compartment_1) /\
    forall(i in 1..4)(compartments[i] != Compartment_1 -> items[i] != Tub_of_Ice_Cream);

include "globals.mzn";

enum Animal = {wolf, rabbit, goat, parrot, tortoise};
array[1..5] of var Animal: pen;

constraint pen[1] = tortoise;
constraint pen[2] = parrot;
constraint pen[3] = goat;
constraint forall(i in 1..5)(pen[i] != pen[i+1] /\ pen[i] != pen[i-1]); % Each pen contains exactly one animal
constraint exists(i in 1..5)(exists(j in (i+1)..5)(pen[i] = rabbit /\ pen[j] = wolf)); % The rabbit is in a lower-numbered pen than the wolf
constraint exists(i in 1..5)(exists(j in 1..5)(pen[i] = wolf /\ pen[j] = rabbit)); % The wolf preys on the rabbit
